/**
 * Exact small-cardinality long-only portfolio reference.
 *
 * The binary support variable marks final holdings.  It is deliberately not
 * a trade-count variable.  For the small declared scope, every support is
 * enumerated and its bounded concave quadratic subproblem is solved by
 * bound-active KKT enumeration.
 */

export const ABSOLUTE_TOLERANCE = 1e-9;
export const RELATIVE_TOLERANCE = 2e-8;
export const FEASIBILITY_TOLERANCE = 2e-9;
export const KKT_TOLERANCE = 2e-7;
export const BOUND_TOLERANCE = 2e-8;
export const SUPPORT_TOLERANCE = 1e-8;
export const PSD_RELATIVE_TOLERANCE = 1e-10;
export const MAX_ASSETS = 12;
export const MAX_CARDINALITY = 6;

