interface Validated {
  mean: number[]; sigma: number[][]; risk: number; current: number[];
  cardinality: number; lower: number[]; upper: number[];
}

interface BestPoint {
  value: number;
  point: number[];
}

function invalid(code: string, message: string): never {
  throw new CardinalityValidationError(code, message);
}

function asReal(value: unknown, name: string): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    invalid("invalid-input", name + " must be a finite real number.");
  }
  return value;
}

function vector(value: unknown, name: string): number[] {
  if (!Array.isArray(value) || value.length === 0) {
    invalid("invalid-input", name + " must be a non-empty numeric array.");
  }
  return value.map((entry, index) => asReal(entry, name + "[" + index + "]"));
}

function matrix(value: unknown, name: string, size: number): number[][] {
  if (!Array.isArray(value) || value.length !== size) {
    invalid("invalid-input", name + " must have " + size + " rows.");
  }
  return value.map((row, rowIndex) => {
    if (!Array.isArray(row) || row.length !== size) {
      invalid("invalid-input", name + " must be " + size + " by " + size + ".");
    }
    return row.map((entry, columnIndex) => asReal(entry, name + "[" + rowIndex + "][" + columnIndex + "]"));
  });
}

function stableSum(values: readonly number[]): number {
  let total = 0;
  let compensation = 0;
  for (const value of values) {
    const candidate = total + value;
    if (Math.abs(total) >= Math.abs(value)) compensation += (total - candidate) + value;
    else compensation += (value - candidate) + total;
    total = candidate;
  }
  return total + compensation;
}

function dot(left: readonly number[], right: readonly number[]): number {
  return stableSum(left.map((value, index) => value * right[index]));
}

function objective(point: readonly number[], mean: readonly number[], covariance: readonly (readonly number[])[], risk: number): number {
  return dot(mean, point) - risk * dot(point, covariance.map((row) => dot(row, point)));
}

function minimumEigenvalue(matrixValue: readonly (readonly number[])[]): number {
  const size = matrixValue.length;
  const work = matrixValue.map((row) => [...row]);
  if (size === 1) return work[0][0];
  const scale = Math.max(...work.flat().map((value) => Math.abs(value)));
  if (scale === 0) return 0;
  for (let sweep = 0; sweep < Math.max(60, 20 * size * size); sweep += 1) {
    let p = 0; let q = 1; let largest = 0;
    for (let row = 0; row < size; row += 1) {
      for (let column = row + 1; column < size; column += 1) {
        const magnitude = Math.abs(work[row][column]);
        if (magnitude > largest) { largest = magnitude; p = row; q = column; }
      }
    }
    if (largest <= 1e-14 * scale) break;
    const app = work[p][p]; const aqq = work[q][q]; const apq = work[p][q];
    const angle = 0.5 * Math.atan2(2 * apq, aqq - app);
    const cosine = Math.cos(angle); const sine = Math.sin(angle);
    for (let index = 0; index < size; index += 1) {
      if (index === p || index === q) continue;
      const aip = work[index][p]; const aiq = work[index][q];
      work[index][p] = cosine * aip - sine * aiq; work[p][index] = work[index][p];
      work[index][q] = sine * aip + cosine * aiq; work[q][index] = work[index][q];
    }
    work[p][p] = cosine * cosine * app - 2 * cosine * sine * apq + sine * sine * aqq;
    work[q][q] = sine * sine * app + 2 * cosine * sine * apq + cosine * cosine * aqq;
    work[p][q] = 0; work[q][p] = 0;
  }
  return Math.min(...work.map((row, index) => row[index]));
}

function solveLinearSystem(matrixValue: readonly (readonly number[])[], right: readonly number[]): number[] | undefined {
  const size = right.length;
  const work = matrixValue.map((row, index) => [...row, right[index]]);
  const scale = Math.max(...matrixValue.flat().map((value) => Math.abs(value)));
  if (scale === 0) return undefined;
  const pivotTolerance = 1e-12 * scale;
  for (let column = 0; column < size; column += 1) {
    let pivot = column;
    for (let row = column + 1; row < size; row += 1) {
      if (Math.abs(work[row][column]) > Math.abs(work[pivot][column])) pivot = row;
    }
    if (Math.abs(work[pivot][column]) <= pivotTolerance) return undefined;
    if (pivot !== column) [work[column], work[pivot]] = [work[pivot], work[column]];
    const pivotValue = work[column][column];
    for (let row = column + 1; row < size; row += 1) {
      const factor = work[row][column] / pivotValue;
      if (factor === 0) continue;
      for (let entry = column; entry <= size; entry += 1) work[row][entry] -= factor * work[column][entry];
    }
  }
  const solution = Array.from({ length: size }, () => 0);
  for (let row = size - 1; row >= 0; row -= 1) {
    let remainder = work[row][size];
    for (let entry = row + 1; entry < size; entry += 1) remainder -= work[row][entry] * solution[entry];
    solution[row] = remainder / work[row][row];
  }
  return solution.every((value) => Number.isFinite(value)) ? solution : undefined;
}

function solveKktSystem(
  hessian: readonly (readonly number[])[], linear: readonly number[], budget: number,
): number[] | undefined {
  // The budget row has unit coefficients while the stationarity rows may be
  // 1e-100 or 1e100. Scale stationarity by the actual objective magnitude,
  // then restore the multiplier to original units after elimination.
  const size = linear.length;
  let stationarityScale = 0;
  for (const row of hessian) for (const value of row) stationarityScale = Math.max(stationarityScale, Math.abs(value));
  for (const value of linear) stationarityScale = Math.max(stationarityScale, Math.abs(value));
  if (stationarityScale === 0 || !Number.isFinite(stationarityScale)) return undefined;
  const system = Array.from({ length: size + 1 }, () => Array.from({ length: size + 1 }, () => 0));
  const right = Array.from({ length: size + 1 }, () => 0);
  for (let row = 0; row < size; row += 1) {
    for (let column = 0; column < size; column += 1) system[row][column] = hessian[row][column] / stationarityScale;
    system[row][size] = 1;
    right[row] = linear[row] / stationarityScale;
  }
  for (let column = 0; column < size; column += 1) system[size][column] = 1;
  right[size] = budget;
  const solution = solveLinearSystem(system, right);
  if (!solution) return undefined;
  solution[size] *= stationarityScale;
  return solution;
}

function validateInputs(
  meanValue: unknown, covarianceValue: unknown, lambdaValue: unknown,
  currentValue: unknown, cardinalityValue: unknown, lowerValue: unknown, upperValue: unknown,
): Validated {
  const mean = vector(meanValue, "mu");
  const size = mean.length;
  const sigma = matrix(covarianceValue, "covariance", size);
  const risk = asReal(lambdaValue, "lambda_risk");
  const current = vector(currentValue, "current");
  if (current.length !== size) invalid("invalid-input", "mu, covariance, and current must align.");
  if (typeof cardinalityValue !== "number" || !Number.isInteger(cardinalityValue)) invalid("invalid-input", "K must be an integer.");
  const cardinality = cardinalityValue;
  if (size > MAX_ASSETS || cardinality > MAX_CARDINALITY) {
    invalid("scope-limit", "the exact reference is limited to n≤" + MAX_ASSETS + " and K≤" + MAX_CARDINALITY + "; use a certified MIP solver for larger inputs.");
  }
  if (cardinality < 1 || cardinality > size) invalid("invalid-cardinality", "K must satisfy 1 ≤ K ≤ n.");
  if (risk < 0) invalid("invalid-input", "lambda_risk must be nonnegative.");
  if (current.some((value) => value < 0)) invalid("invalid-input", "current holdings must be nonnegative.");
  const currentTotal = stableSum(current);
  if (!Number.isFinite(currentTotal)) invalid("wealth-overflow", "current holdings sum must be finite.");
  if (Math.abs(currentTotal - 1) > 10 * FEASIBILITY_TOLERANCE) invalid("current-not-normalized", "current holdings must sum to one.");
  const lower = lowerValue === undefined || lowerValue === null ? Array.from({ length: size }, () => 0) : vector(lowerValue, "lower");
  const upper = upperValue === undefined || upperValue === null ? Array.from({ length: size }, () => 1) : vector(upperValue, "upper");
  if (lower.length !== size || upper.length !== size) invalid("invalid-input", "lower and upper bounds must align with mu.");
  lower.forEach((value, index) => {
    const high = upper[index];
    if (value < 0 || high < 0 || value > high || high > 1 || !Number.isFinite(value + high)) {
      invalid("invalid-bound", "lower[" + index + "] and upper[" + index + "] must satisfy 0 ≤ lower ≤ upper ≤ 1.");
    }
  });
  const scale = Math.max(...sigma.flat().map((value) => Math.abs(value)));
  if (scale === 0) {
    if (risk > 0) invalid("singular-covariance", "positive risk aversion requires a positive-definite covariance in the exact reference scope.");
  } else {
    const symmetryTolerance = 1e-12 * scale;
    for (let row = 0; row < size; row += 1) {
      for (let column = 0; column < row; column += 1) {
        if (Math.abs(sigma[row][column] - sigma[column][row]) > symmetryTolerance) invalid("indefinite-covariance", "covariance must be symmetric at the matrix scale.");
      }
    }
    const minimum = minimumEigenvalue(sigma);
    if (minimum < -PSD_RELATIVE_TOLERANCE * scale) invalid("indefinite-covariance", "covariance must be positive semidefinite.");
    if (risk > 0 && minimum <= PSD_RELATIVE_TOLERANCE * scale) invalid("singular-covariance", "positive risk aversion requires a positive-definite covariance in the exact active-set reference.");
  }
  return { mean, sigma, risk, current, cardinality, lower, upper };
}

function pointIsBetter(
  point: readonly number[], best: BestPoint | undefined,
  mean: readonly number[], sigma: readonly (readonly number[])[], risk: number,
): BestPoint | undefined {
  const value = objective(point, mean, sigma, risk);
  if (!Number.isFinite(value)) throw new CardinalityNumericalError("nonfinite-objective", "continuous subproblem produced a non-finite objective.");
  const comparisonTolerance = best === undefined ? 0 : RELATIVE_TOLERANCE * Math.max(Math.abs(value), Math.abs(best.value));
  return best === undefined || value > best.value + comparisonTolerance ? { value, point: [...point] } : best;
}

function continuousLinearSupport(
  mean: readonly number[], sigma: readonly (readonly number[])[], risk: number,
  lower: readonly number[], upper: readonly number[], support: readonly number[],
): BestPoint | undefined {
  let best: BestPoint | undefined;
  const dimension = support.length;
  for (let freePosition = 0; freePosition < dimension; freePosition += 1) {
    const fixedPositions = Array.from({ length: dimension }, (_, position) => position).filter((position) => position !== freePosition);
    for (let mask = 0; mask < (1 << fixedPositions.length); mask += 1) {
      const point = Array.from({ length: mean.length }, () => 0);
      fixedPositions.forEach((position, bit) => {
        const index = support[position];
        point[index] = mask & (1 << bit) ? upper[index] : lower[index];
      });
      const freeIndex = support[freePosition];
      point[freeIndex] = 1 - stableSum(point);
      if (point[freeIndex] < lower[freeIndex] - FEASIBILITY_TOLERANCE || point[freeIndex] > upper[freeIndex] + FEASIBILITY_TOLERANCE) continue;
      point[freeIndex] = Math.min(upper[freeIndex], Math.max(lower[freeIndex], point[freeIndex]));
      if (Math.abs(stableSum(point) - 1) > 10 * FEASIBILITY_TOLERANCE) continue;
      best = pointIsBetter(point, best, mean, sigma, risk);
    }
  }
  return best;
}

function continuousSupport(
  mean: readonly number[], sigma: readonly (readonly number[])[], risk: number,
  lower: readonly number[], upper: readonly number[], support: readonly number[],
): BestPoint | undefined {
  const supportLower = stableSum(support.map((index) => lower[index]));
  const supportUpper = stableSum(support.map((index) => upper[index]));
  if (supportLower > 1 + FEASIBILITY_TOLERANCE || supportUpper < 1 - FEASIBILITY_TOLERANCE) return undefined;
  if (risk === 0) return continuousLinearSupport(mean, sigma, risk, lower, upper, support);

  let best: BestPoint | undefined;
  const dimension = support.length;
  const stateCount = 3 ** dimension;
  for (let code = 0; code < stateCount; code += 1) {
    let stateCode = code;
    const fixed = Array.from({ length: mean.length }, () => 0);
    const fixedState = new Map<number, number>();
    const free: number[] = [];
    support.forEach((index) => {
      const state = stateCode % 3; stateCode = Math.floor(stateCode / 3);
      if (state === 1) free.push(index);
      else { fixed[index] = state === 0 ? lower[index] : upper[index]; fixedState.set(index, state); }
    });
    const fixedTotal = stableSum(fixed);
    if (free.length === 0) {
      if (Math.abs(fixedTotal - 1) <= 10 * FEASIBILITY_TOLERANCE) best = pointIsBetter(fixed, best, mean, sigma, risk);
      continue;
    }
    const dimensionFree = free.length;
    const hessian = Array.from({ length: dimensionFree }, () => Array.from({ length: dimensionFree }, () => 0));
    const linear = Array.from({ length: dimensionFree }, () => 0);
    free.forEach((index, row) => {
      free.forEach((other, column) => { hessian[row][column] = 2 * risk * sigma[index][other]; });
      linear[row] = mean[index] - 2 * risk * dot(sigma[index], fixed);
    });
    const solution = solveKktSystem(hessian, linear, 1 - fixedTotal);
    if (!solution) continue;
    const point = [...fixed];
    free.forEach((index, row) => { point[index] = solution[row]; });
    if (Math.abs(stableSum(point) - 1) > 10 * FEASIBILITY_TOLERANCE) continue;
    if (support.some((index) => point[index] < lower[index] - BOUND_TOLERANCE || point[index] > upper[index] + BOUND_TOLERANCE)) continue;
    support.forEach((index) => { point[index] = Math.min(upper[index], Math.max(lower[index], point[index])); });
    const multiplier = solution[dimensionFree];
    const gradients = support.map((index) => mean[index] - 2 * risk * dot(sigma[index], point));
    const stationarityScale = Math.max(
      ...gradients.map((value) => Math.abs(value)),
      Math.abs(multiplier),
      ...support.map((index) => Math.abs(mean[index]) + 2 * risk * stableSum(sigma[index].map((value, column) => Math.abs(value) * Math.abs(point[column])))),
    );
    const kktTolerance = KKT_TOLERANCE * stationarityScale;
    const valid = support.every((index, supportPosition) => {
      const gradient = gradients[supportPosition];
      const state = fixedState.get(index);
      const width = upper[index] - lower[index];
      if (state === 0 && width > BOUND_TOLERANCE) return gradient <= multiplier + kktTolerance;
      if (state === 2 && width > BOUND_TOLERANCE) return gradient >= multiplier - kktTolerance;
      return state === undefined ? Math.abs(gradient - multiplier) <= kktTolerance : true;
    });
    if (valid) best = pointIsBetter(point, best, mean, sigma, risk);
  }
  return best;
}

function supportTotal(size: number, cardinality: number): number {
  let total = 0;
  for (let count = 1; count <= cardinality; count += 1) {
    let choose = 1;
    for (let factor = 1; factor <= count; factor += 1) choose = choose * (size - count + factor) / factor;
    total += Math.round(choose);
  }
  return total;
}

function supports(size: number, cardinality: number): number[][] {
  const result: number[][] = [];
  const visit = (start: number, target: number, prefix: number[]) => {
    if (prefix.length === target) { result.push([...prefix]); return; }
    for (let index = start; index < size; index += 1) visit(index + 1, target, [...prefix, index]);
  };
  for (let count = 1; count <= cardinality; count += 1) visit(0, count, []);
  return result;
}

export function optimizeCardinalityConstrained(
  mu: unknown, covariance: unknown, lambdaRisk: unknown, current: unknown, K: unknown,
  options: { lower?: unknown; upper?: unknown; maxSupports?: unknown } = {},
): CardinalityResult {
  const checked = validateInputs(mu, covariance, lambdaRisk, current, K, options.lower, options.upper);
  const allSupports = supports(checked.mean.length, checked.cardinality);
  const totalSupports = allSupports.length;
  let supportLimit = totalSupports;
  if (options.maxSupports !== undefined) {
    if (typeof options.maxSupports !== "number" || !Number.isInteger(options.maxSupports) || options.maxSupports <= 0) invalid("invalid-input", "max_supports must be a positive integer.");
    supportLimit = Math.min(options.maxSupports, totalSupports);
  }
  let best: BestPoint | undefined;
  let enumerated = 0;
  for (const support of allSupports) {
    if (enumerated >= supportLimit) break;
    enumerated += 1;
    const candidate = continuousSupport(checked.mean, checked.sigma, checked.risk, checked.lower, checked.upper, support);
    const comparisonTolerance = best === undefined ? 0 : RELATIVE_TOLERANCE * Math.max(Math.abs(candidate?.value ?? 0), Math.abs(best.value));
    if (candidate && (best === undefined || candidate.value > best.value + comparisonTolerance)) best = candidate;
  }
  const complete = enumerated === totalSupports;
  if (best === undefined) {
    return {
      status: complete ? "infeasible" : "incomplete", weights: null, selected: null, trade: null,
      objective: null, bestBound: null, relativeGap: null, enumeratedSupports: enumerated,
      totalSupports, certificate: {
        kind: "exhaustive-support-enumeration", complete,
        globalOptimality: complete ? "all supports were checked; no continuous support was feasible" : "no incumbent was found before the support limit",
      },
    };
  }
  const weights = best.point;
  const selected = weights.map((value) => value > 0 ? 1 : 0);
  const trade = weights.map((value, index) => value - checked.current[index]);
  const realizedSupport = selected.reduce((total: number, value: number) => total + value, 0);
  const tradeSupport = trade.filter((value) => Math.abs(value) > SUPPORT_TOLERANCE).length;
  return {
    status: complete ? "optimal" : "feasible", weights, selected, trade,
    objective: best.value, bestBound: complete ? best.value : null, relativeGap: complete ? 0 : null,
    enumeratedSupports: enumerated, totalSupports, realizedSupport, tradeSupport,
    certificate: {
      kind: "exhaustive-support-enumeration", complete, continuousKkt: true,
      globalOptimality: complete ? "all supports and continuous KKT active sets were checked" : "incumbent only; support enumeration stopped before a proof",
    },
  };
}
